//
// cartwright_steger.h: the Cartwright-Steger surface X = Pi\B^2, its fundamental group Pi in PU(2,1) over Z[zeta_12],
// and the homomorphism f: Pi -> Z^2. namespace zippers::cs.
//
// THE GROUP. Pi is generated by the elements a1, a2, a3 of Cartwright-Koziarz-Yeung (arXiv:1412.4137, Theorem 2): a
// torsion-free subgroup of index 864 in the arithmetic lattice Gamma-bar = <u, v, b> of PU(2,1). In CKY's primed
// coordinates its elements are 3x3 matrices over Z[zeta] (geometry/pu21/pu21.h, the backend zippers::PU21).
//
// THE HOMOMORPHISM. H_1(Pi) = Z^2 by f(a1) = (1,3), f(a2) = (-2,1), f(a3) = (-1,-1), and phi = the first coordinate
// of f. Every element of a ball carries its f-value (its label in the store, FVal), and f is checked to be well
// defined whenever an element is reached by two different paths (the count that enumerate returns).
//
// THE WORDS of the substitution files are in the letters a1, a2, a3 and A1, A2, A3 (A = inverse), and "1".
//
// Moved unchanged from legacy/s3/csgroup.h (the CKY data, setup, Gen, agens, enumerate, word, guard, geogens) and
// legacy/s3/zipcore.h (parse_word, shell_radii, RootInfo, roots_info, find_roots): static -> inline, the file-scope
// statics as C++17 inline variables, namespace zippers::cs, the store zippers::Store<PU21, FVal> in place of the
// legacy Store (labels .f0, .f1 in place of the arrays f0, f1). Two changes of form:
//   - setup() no longer computes F' and F'^-1: they are constants of pu21.h (FP, FPI);
//   - enumerate calls the backend: PU21::product_key and PU21::key_displacement in place of prodkey and
//     hdist(col[2]), and PU21::normal(PU21::mul(g, s)) in place of mrotk(mmul(g, s), k) with the k of prodkey, which
//     is the same element (k is normk of the product's (3,3) entry); tests/unit/test_pu21.cc checks both, and that
//     the balls are the legacy ones, element by element.
// The checks of the root balls are in cartwright_steger_roots.h.

#pragma once

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <functional>
#include <queue>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

#include "geometry/pu21/pu21.h"
#include "store/store.h"

namespace zippers {
namespace cs {

// the label of an element in a store: its f-value, f0 = phi and f1
struct FVal { int f0, f1; };

typedef zippers::Store<PU21, FVal> Store;

// ---------------------------------------------------------------------------------------
// The data of Cartwright-Steger / CKY, in primed coordinates (set by setup()).

inline M3 U, V, B, J;         // u', v', b', j
inline M3 A[3];               // a1, a2, a3 (normalised)
inline const int FA[3][2] = { {1,3}, {-2,1}, {-1,-1} };     // f(a_i)

inline void setup()
{
    Zz one = Z(1,0,0,0);
    U = mzero();
    U.e[0][0] = Z(0,-1,1,1);  U.e[0][1] = Z(1,-1,0,0);
    U.e[1][0] = Z(-1,0,1,1);  U.e[1][1] = Z(0,1,0,-1);
    U.e[2][2] = one;
    V = mzero();
    V.e[0][0] = Z(0,0,0,1);
    V.e[1][0] = Z(-1,-1,1,1); V.e[1][1] = one;
    V.e[2][2] = one;
    B = mzero();
    B.e[0][0] = one;
    B.e[1][0] = Z(2,2,-1,-2); B.e[1][1] = Z(-1,-1,1,1); B.e[1][2] = Z(0,0,-1,-1);
    B.e[2][0] = Z(0,1,1,0);   B.e[2][1] = Z(-1,0,0,-1); B.e[2][2] = Z(1,1,0,-1);
    J = mzero();
    J.e[0][0] = Z(0,1,0,0); J.e[1][1] = Z(0,1,0,0); J.e[2][2] = one;

    M3 Ui = minv(U), Vi = minv(V);
    // a1 = v u v^-1 j^4 b u v j^2
    A[0] = mmul(mmul(mmul(mmul(mmul(mmul(mmul(V, U), Vi), mpow(J,4)), B), U), V), mpow(J,2));
    // a2 = v^2 u b u v^-1 u v^2 j
    A[1] = mmul(mmul(mmul(mmul(mmul(mmul(mmul(mpow(V,2), U), B), U), Vi), U), mpow(V,2)), J);
    // a3 = u^-1 v^2 u j^9 b v^-1 u v^-1 j^8
    A[2] = mmul(mmul(mmul(mmul(mmul(mmul(mmul(mmul(Ui, mpow(V,2)), U), mpow(J,9)), B), Vi), U), Vi), mpow(J,8));
    for (int i = 0; i < 3; i++) A[i] = mnormal(A[i]);
}

// ---------------------------------------------------------------------------------------
// Generators a_i^{+-1}, with labels for words: "a1".."a3", "A1".."A3" (A = inverse)

struct Gen { M3 m; int f0, f1; std::string name; };

inline std::vector<Gen> agens()
{
    std::vector<Gen> G;
    for (int i = 0; i < 3; i++) {
        G.push_back({A[i], FA[i][0], FA[i][1], "a" + std::to_string(i+1)});
        G.push_back({mnormal(minv(A[i])), -FA[i][0], -FA[i][1], "A" + std::to_string(i+1)});
    }
    return G;
}

// best-first enumeration of { g : d(o, g o) <= D } by right multiplication by the generators,
// discarding anything farther than D.  Returns the number of f-inconsistencies found.
inline long enumerate(Store& S, const std::vector<Gen>& G, double D)
{
    S.add(PU21::normal(PU21::identity()), -1, -1, 0, FVal{0, 0}, 0.f);
    typedef std::pair<float,int> P;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
    pq.push({0.f, 0});
    std::vector<char> done(1, 0);
    long bad = 0;
    while (!pq.empty()) {
        int i = pq.top().second; pq.pop();
        if (done[i]) continue;
        done[i] = 1;
        M3 g = S.load(i);
        for (size_t j = 0; j < G.size(); j++) {
            PU21::Key key = PU21::product_key(g, G[j].m);
            int a0 = S.label[i].f0 + G[j].f0, a1 = S.label[i].f1 + G[j].f1;
            int f = S.find(key);
            if (f >= 0) { if (S.label[f].f0 != a0 || S.label[f].f1 != a1) bad++; continue; }
            double d = PU21::key_displacement(key);
            if (d > D) continue;
            M3 h = PU21::normal(PU21::mul(g, G[j].m));
            int n = S.add(h, i, j, S.depth[i] + 1, FVal{a0, a1}, (float)d);
            pq.push({(float)d, n});
            done.push_back(0);
        }
    }
    return bad;
}

// the word of element idx: the names of the generators on its path, or "1"
inline std::string word(const Store& S, int idx, const std::vector<Gen>& G)
{
    std::string w;
    for (int g : S.path(idx)) { if (!w.empty()) w += " "; w += G[g].name; }
    return w.empty() ? "1" : w;
}

// The ball B(D) has about sinh^4(D/2) elements (vol X = 8 pi^2), at ~170 bytes each.
// Refuse anything that would not fit comfortably in memory.
inline void guard(double D)
{
    double n = std::pow(std::sinh(D/2), 4);
    if (n > 4e6) {
        fprintf(stderr, "refusing to enumerate B(%.2f): about %.2g elements, more than the 4e6 memory guard\n", D, n);
        exit(1);
    }
}

// A geometric generating set: the elements g != 1 with d(o, g o) <= rhog that the search with the generators a_i^{+-1}
// through B(rhog + 3) finds (margin 3).  The names are a-words.
// roots_info, find_roots and shell_radii search with S = geogens(4.5); cartwright_steger_roots.h checks those searches
// (zipper3 --stats). The code is the legacy code: another S would change the outputs.
inline std::vector<Gen> geogens(double rhog)
{
    std::vector<Gen> A6 = agens();
    Store S;
    guard(rhog + 3);
    enumerate(S, A6, rhog + 3);
    std::vector<Gen> G;
    for (size_t i = 1; i < S.size(); i++)
        if (S.dist[i] <= rhog) G.push_back({S.load(i), S.label[i].f0, S.label[i].f1, word(S, i, A6)});
    return G;
}

// ---------------------------------------------------------------------------------------
// Words of the substitution files, and the roots of the renderer (legacy zipcore.h)

// an a-word ("a1 A3 a2", or "1") -> its element, normalised
inline M3 parse_word(const std::string& w)
{
    M3 g = mid();
    std::istringstream is(w);
    std::string tok;
    while (is >> tok) {
        if (tok == "1") continue;
        if (tok.size() != 2 || (tok[0] != 'a' && tok[0] != 'A') || tok[1] < '1' || tok[1] > '3') {
            fprintf(stderr, "bad letter '%s' in a word\n", tok.c_str()); exit(1);
        }
        int i = tok[1] - '1';
        g = mmul(g, tok[0] == 'a' ? A[i] : minv(A[i]));
    }
    return mnormal(g);
}

// the distinct values of d(o, g o) up to rmax: the radii at which the set of roots changes
inline std::vector<double> shell_radii(double rmax)
{
    std::vector<Gen> G = geogens(4.5);
    Store B;
    guard(rmax + 0.5);
    enumerate(B, G, rmax + 0.5);
    std::vector<double> d;
    for (size_t i = 0; i < B.size(); i++) if (B.dist[i] <= rmax) d.push_back(B.dist[i]);
    std::sort(d.begin(), d.end());
    std::vector<double> r;
    for (double x : d) if (r.empty() || x > r.back() + 1e-4) r.push_back(x);
    return r;
}

// the elements of B(R), nearest first, with their f-values and a-words
struct RootInfo { M3 g; double d; int f0, f1; std::string word; };

inline std::vector<RootInfo> roots_info(double R)
{
    std::vector<Gen> G = geogens(4.5);
    Store B;
    guard(R + 0.5);
    enumerate(B, G, R + 0.5);
    std::vector<int> idx;
    for (size_t i = 0; i < B.size(); i++) if (B.dist[i] <= R) idx.push_back(i);
    std::stable_sort(idx.begin(), idx.end(), [&](int a, int b) { return B.dist[a] < B.dist[b]; });
    std::vector<RootInfo> r;
    for (int i : idx) r.push_back({B.load(i), B.dist[i], B.label[i].f0, B.label[i].f1, word(B, i, G)});
    return r;
}

inline void find_roots(double R, std::vector<M3>& roots)
{
    roots.clear();
    for (const RootInfo& x : roots_info(R)) roots.push_back(x.g);
}

// ---------------------------------------------------------------------------------------
// THE FOCUS CENTRE: an element h of Pi whose orbit point h o is near the point o_F at distance L from o towards
// the point xi of S^3 (the centre of a zoomed view). Then h B(R) is the ball of radius R about h o (render/world.h:
// the focus ball).
// In the unit ball of C^2 (the coordinates of ballpoint and spoint, geometry/pu21/pu21.h) o is 0, the geodesic towards
// xi is the radius to it, and o_F = tanh(L/2) xi, since d(o, z) = 2 atanh |z| (d(o, g o) = 2 acosh |g_33|: holomorphic
// curvature -1); and cosh(d(z, w)/2) = |1 - <z, w>| / sqrt((1 - |z|^2)(1 - |w|^2)).
// THE WALK: from h = 1, h <- h s for the element s of G (the geometric generators geogens(4.5) of the roots) that brings
// h o nearest to o_F, while one brings it nearer; then once the products s s' of two of them, and again, until neither
// brings it nearer. The elements are exact; the choices are made in doubles. Pi is cocompact, so the walk ends near
// o_F (its distance is printed by zipper3 --focus).
struct FocusCentre3 {
    M3 h;                              // in Pi, normalised
    double L = 0;                      // the focus distance
    double dist = 0;                   // d(h o, o_F)
    double disp = 0;                   // d(o, h o)
    int steps = 0;                     // the steps of the walk (one or two generators each)
    std::string word;                  // h as a word in the a-generators
};

// d(z, w) for two points of the unit ball of C^2 (4 reals each)
inline double ball_distance(const double z[4], const double w[4])
{
    std::complex<double> z1(z[0], z[1]), z2(z[2], z[3]), w1(w[0], w[1]), w2(w[2], w[3]);
    double nz = 1 - std::norm(z1) - std::norm(z2), nw = 1 - std::norm(w1) - std::norm(w2);
    double c = std::abs(1.0 - z1*std::conj(w1) - z2*std::conj(w2))/std::sqrt(nz*nw);
    return c <= 1 ? 0 : 2*std::acosh(c);
}

// d(g o, p) for a point p of the ball
inline double orbit_distance3(const M3& g, const double p[4])
{
    cpx c[3] = {zval(g.e[0][2]), zval(g.e[1][2]), zval(g.e[2][2])};
    double z[4];
    ballpoint(c, z);
    return ball_distance(z, p);
}

inline FocusCentre3 focus_centre3(const double xi[4], double L, const std::vector<Gen>& G)
{
    double nx = std::sqrt(xi[0]*xi[0] + xi[1]*xi[1] + xi[2]*xi[2] + xi[3]*xi[3]);
    double p[4];
    for (int k = 0; k < 4; k++) p[k] = std::tanh(L/2)*xi[k]/nx;
    FocusCentre3 fc;
    fc.L = L;
    M3 h = PU21::normal(PU21::identity());
    double dh = orbit_distance3(h, p);
    std::vector<int> word;
    bool pairs = false;
    for (int step = 0; step < 10000; step++) {
        int b1 = -1, b2 = -1;
        double bd = dh;
        for (size_t i = 0; i < G.size(); i++) {
            M3 x = mmul(h, G[i].m);
            if (!pairs) {
                double d = orbit_distance3(x, p);
                if (d < bd - 1e-12) { bd = d; b1 = (int)i; }
            } else
                for (size_t j = 0; j < G.size(); j++) {
                    double d = orbit_distance3(mmul(x, G[j].m), p);
                    if (d < bd - 1e-12) { bd = d; b1 = (int)i; b2 = (int)j; }
                }
        }
        if (b1 < 0) {
            if (pairs) break;
            pairs = true;                  // no single step brings h o nearer: try the pairs once
            continue;
        }
        h = mnormal(mmul(h, G[b1].m));
        word.push_back(b1);
        if (b2 >= 0) { h = mnormal(mmul(h, G[b2].m)); word.push_back(b2); }
        dh = bd;
        fc.steps++;
        pairs = false;
    }
    fc.h = h;
    fc.dist = dh;
    fc.disp = PU21::displacement(h);
    for (int i : word) { if (!fc.word.empty()) fc.word += " "; fc.word += G[i].name; }
    if (fc.word.empty()) fc.word = "1";
    return fc;
}

}  // namespace cs
}  // namespace zippers
